def configure_legacy_settings(app: FlaskBB):
    """Translates the settings of config files generated by FlaskBB 2.x."""
    legacy_celery_config = {
        key: value
        for key, value in app.raw_config.get_namespace("CELERY_").items()
        if key != "config"
    }
    for key in legacy_celery_config:
        warnings.warn(
            f"CELERY_{key.upper()} is deprecated and will be removed in FlaskBB 4.0, set "
            f"{key!r} in CELERY_CONFIG instead.",
            RemovedInFlaskBB4,
            stacklevel=2,
        )
        app.raw_config.pop(f"CELERY_{key.upper()}", None)  # pyright: ignore[reportUnknownMemberType]
    if legacy_celery_config:
        # a new dict, it would change DefaultConfig.CELERY_CONFIG otherwise
        app.config["CELERY_CONFIG"] = {**app.config["CELERY_CONFIG"], **legacy_celery_config}

    cache_type = LEGACY_CACHE_TYPES.get(app.config["CACHE_TYPE"])
    if cache_type is not None:
        warnings.warn(
            f"CACHE_TYPE {app.config['CACHE_TYPE']!r} is deprecated and will be removed in "
            f"FlaskBB 4.0, use {cache_type!r} instead.",
            RemovedInFlaskBB4,
            stacklevel=2,
        )
        app.config["CACHE_TYPE"] = cache_type

    if "RATELIMIT_STORAGE_URL" in app.config and "RATELIMIT_STORAGE_URI" not in app.config:
        warnings.warn(
            "RATELIMIT_STORAGE_URL is deprecated and will be removed in FlaskBB 4.0, use "
            "RATELIMIT_STORAGE_URI instead.",
            RemovedInFlaskBB4,
            stacklevel=2,
        )
        app.config["RATELIMIT_STORAGE_URI"] = app.config["RATELIMIT_STORAGE_URL"]

def configure_context_processors(app: FlaskBB):
    """Configures the context processors."""

    @app.context_processor
    def inject_flaskbb_config():
        """Injects the ``flaskbb_config`` config variable into the
        templates.
        """
        return dict(
            flaskbb_config=flaskbb_config,
            format_date=format_date,
            current_permissions=current_permissions,
        )

    @app.context_processor
    def inject_now():
        """Injects the current time."""
        return dict(now=datetime.now(UTC))

