def configure_before_handlers(app: FlaskBB):
    """Configures the before request handlers."""

    @app.before_request
    def update_lastseen():
        """Updates `lastseen` of the authenticated user."""
        if not current_user.is_authenticated:
            return
        now = time_utcnow()
        if current_user.lastseen and now - current_user.lastseen < timedelta(minutes=1):
            return
        current_user.lastseen = now
        db.session.add(current_user)
        commit_without_expiring()

    if app.config["REDIS_ENABLED"]:

        @app.before_request
        def mark_current_user_online():
            if current_user.is_authenticated:
                mark_online(current_user.id)
            elif request.remote_addr:
                mark_online(request.remote_addr, guest=True)

    pluggy.hook.flaskbb_request_processors(app=app)

