    # if a user is logged in, use the locale from the user settings
    if current_user and current_user.is_authenticated and current_user.language:
        return current_user.language
    # otherwise we will just fallback to the default language
    return flaskbb_config["DEFAULT_LANGUAGE"]

def configure_logging(app: FlaskBB):
    """Configures logging."""
    if app.config.get("USE_DEFAULT_LOGGING"):
        configure_default_logging(app)

    log_conf_file = app.config["LOG_CONF_FILE"]
    if log_conf_file:
        logging.config.fileConfig(log_conf_file, disable_existing_loggers=False)

    if app.config["SQLALCHEMY_ECHO"]:
        # Ref: http://stackoverflow.com/a/8428546
        @event.listens_for(Engine, "before_cursor_execute")
        def before_cursor_execute(
            conn: Connection,
            cursor: Any,
            statement: str,
            parameters: Any,
            context: Any,
            executemany: bool,
        ) -> None:
            conn.info.setdefault("query_start_time", []).append(time.time())

        @event.listens_for(Engine, "after_cursor_execute")
        def after_cursor_execute(
            conn: Connection,
            cursor: Any,
            statement: str,
            parameters: Any,
            context: Any,
            executemany: bool,
        ) -> None:
            total = time.time() - conn.info["query_start_time"].pop(-1)
            app.logger.debug("Total Time: %f", total)

@event.listens_for(Engine, "before_cursor_execute")
def before_cursor_execute(
    conn: Connection,
    cursor: Any,
    statement: str,
    parameters: Any,
    context: Any,
    executemany: bool,
) -> None:
    conn.info.setdefault("query_start_time", []).append(time.time())

def configure_default_logging(app: FlaskBB):
    # Load default logging config
    logging.config.dictConfig(app.config["LOG_DEFAULT_CONF"])

    if app.config["SEND_LOGS"]:
        configure_mail_logs(app)

def upgrade_installed_plugin_settings(app: FlaskBB):
    """Adds the settings an installed plugin registered after it was installed.

    Needs the loaded setting registry, a plugin's settings group is unknown before.
    """
    with app.app_context():
        try:
            plugins = db.session.execute(sa.select(PluginRegistry)).scalars().all()
            for plugin in plugins:
                if plugin.is_updatable:
                    logger.info(f"Updating installed plugin: {plugin.name}")
                    plugin.add_settings()
        except (OperationalError, ProgrammingError) as exc:
            # e.g. 'flaskbb db upgrade' creates the app before it migrates the settings table
            logger.debug("Database is not installed or migrated yet.", exc_info=exc)
            db.session.rollback()

