class Login(MethodView):
    decorators = [anonymous_required]

    def __init__(
        self,
        authentication_manager_factory: Callable[[], "PluginAuthenticationManager"],
    ):
        self.authentication_manager_factory = authentication_manager_factory

    def form(self):
        return LoginForm()

    def get(self):
        return render_template("auth/login.html", form=self.form())

    def post(self):
        form = self.form()
        if form.validate_on_submit():
            auth_manager = self.authentication_manager_factory()
            try:
                # every field below is DataRequired/InputRequired, so once
                # validate_on_submit() has passed .data is never empty - the
                # 'or ""' is only to satisfy the type checker.
                user = auth_manager.authenticate(
                    identifier=form.login.data or "", secret=form.password.data or ""
                )
                login_user(user, remember=form.remember_me.data)
                return redirect_or_next(url_for("forum.index"), False)
            except StopAuthentication as e:
                flash(e.reason, "danger")
            except Exception:
                flash(_("Unrecoverable error while handling login"))

        return render_template("auth/login.html", form=form)

