    migrations, with branch-per-plugin support (e.g. ``flaskbb db revision
    --branch <plugin_name>``)."""
    ctx.obj = current_app.extensions["alembic"]

def _is_revision_id(alembic: Alembic, target: str) -> bool:
    # alembic also resolves unique prefixes, "9" would find 933bd7d807c4
    try:
        revision = alembic.script_directory.revision_map.get_revision(target)
    except ResolutionError:
        return False
    return revision is not None and revision.revision == target

@db.command()
@click.pass_obj
@click.argument("target", default="heads")
@click.option(
    "--skip-missing",
    is_flag=True,
    help="Upgrades around the revisions of plugins that are no longer installed. "
    "Their rows stay in the database.",
)
def upgrade(alembic: Alembic, target: str = "heads", skip_missing: bool = False):
    """Run migrations to upgrade the database."""
    # Flask-Alembic's upgrade reads a number as a revision id prefix first,
    # "9" would upgrade to 933bd7d807c4 instead of going up nine revisions
    try:
        steps = int(target)
    except ValueError:
        pass
    else:
        if not _is_revision_id(alembic, target):
            target = f"{abs(steps):+d}"

    alembic.upgrade(target, skip_missing=skip_missing)

@db.command()
@click.pass_obj
@click.argument("target", default="-1")
def downgrade(alembic: Alembic, target: str = "-1"):
    """Run migrations to downgrade the database."""
    # Flask-Alembic's downgrade reads every number as the count of revisions
    # to go back, but FlaskBB's revision ids are numbers (timestamps) as well
    try:
        steps = int(target)
    except ValueError:
        pass
    else:
        if not _is_revision_id(alembic, target):
            target = str(-abs(steps))

    alembic.downgrade(target)

