    if plugin:
        validate_plugin(plugin)
        click.secho(
            f"[+] Adding new language {lang} for plugin {plugin}...",
            fg="cyan",
        )
        add_plugin_translations(plugin, lang)
    else:
        click.secho(f"[+] Adding new language {lang}...", fg="cyan")
        add_translations(lang)


