class EmptyValue:
    """
    Represents an empty change set value when None is a valid value
    to apply to the model.

    This class is a singleton.
    """

    __slots__ = ()

    def __new__(cls):
        # hack to cut down on instances
        global empty
        if empty is None:
            empty = super(EmptyValue, EmptyValue).__new__(cls)
        return empty

    @override
    def __eq__(self, other: Any):
        return isinstance(other, EmptyValue) or (isclass(other) and issubclass(other, EmptyValue))

    def __bool__(self):
        return False

    __nonzero__ = __bool__

def __new__(cls):
    # hack to cut down on instances
    global empty
    if empty is None:
        empty = super(EmptyValue, EmptyValue).__new__(cls)
    return empty

@override
def __eq__(self, other: Any):
    return isinstance(other, EmptyValue) or (isclass(other) and issubclass(other, EmptyValue))

def is_empty(value: Any, consider_none: bool = False):
    """
    Helper to check if an arbitrary value is an EmptyValue
    """
    return empty == value or (consider_none and value is None)

