def drop_foreign_keys(batch_op, inspector, table_name, *columns):
    # The existing foreign keys are named differently depending on how the
    # database was created: naming convention names when it was built by
    # these migrations, dialect defaults (conversations_user_id_fkey,
    # conversations_ibfk_1) for installs from before 2018. Match by column.
    for foreign_key in inspector.get_foreign_keys(table_name):
        constrained = foreign_key["constrained_columns"]
        if foreign_key["name"] and len(constrained) == 1 and constrained[0] in columns:
            batch_op.drop_constraint(foreign_key["name"], type_="foreignkey")

