def _emit_on_create(
    ddl: Any, target: Any, bind: Any, tables: Any = None, state: Any = None, **kw: Any
) -> bool:
    # Only build the FTS5 schema when create_all() runs against a SQLite
    # database with this backend actually selected - so a create_all() on
    # any other backend (e.g. the sql test suite) leaves these
    # tables untouched.
    if bind.dialect.name != "sqlite":
        return False
    try:
        return current_app.config.get("SEARCH_BACKEND") == "sqlite"  # pyright: ignore[reportUnknownMemberType, reportUnknownVariableType]
    except RuntimeError:
        return False

def _register_create_all_ddl() -> None:
    for model, table, cols in INDEX_SPECS:
        for statement in _create_statements(table, cols):
            event.listen(
                model.__table__,
                "after_create",
                DDL(statement).execute_if(callable_=_emit_on_create),
            )

class SQLiteSearchBackend(SearchBackend):
    """Full-text search backed by SQLite FTS5 virtual tables."""

    @override
    def index(self, instance: Model) -> None:
        pass

    @override
    def update(self, instance: Model) -> None:
        pass

    @override
    def remove(self, instance: Model) -> None:
        pass

    @override
    def reindex(self, models: Sequence[ModelT] | None = None) -> None:
        tables = (
            _FTS_TABLES.values()
            if models is None
            else [_FTS_TABLES[m] for m in models if m in _FTS_TABLES]
        )
        for fts in tables:
            db.session.execute(text(f"INSERT INTO {fts}({fts}) VALUES ('rebuild')"))
        db.session.commit()

    def _ranked_ids(self, fts: str, fts_query: str) -> list[int]:
        # `fts` is an internal constant, never user input. bm25() returns
        # a lower score for better matches, so ascending order is best-first.
        stmt = text(f"SELECT rowid FROM {fts} WHERE {fts} MATCH :q ORDER BY bm25({fts}) LIMIT :lim")
        rows = db.session.execute(stmt, {"q": fts_query, "lim": _SEARCH_LIMIT})
        return list(rows.scalars())

    def _topic_body_ids(self, fts_query: str) -> list[int]:
        # A topic also matches on its opening post's body (parity with the
        # `sql` backend), indexed in posts_fts.
        stmt = text(
            "SELECT t.id FROM topics t "
            "JOIN posts_fts ON posts_fts.rowid = t.first_post_id "
            "WHERE posts_fts MATCH :q ORDER BY bm25(posts_fts) LIMIT :lim"
        )
        rows = db.session.execute(stmt, {"q": fts_query, "lim": _SEARCH_LIMIT})
        return list(rows.scalars())

    @override
    def search(self, model: ModelT, query: str) -> Select[Any]:
        fts = _FTS_TABLES.get(model)
        if fts is None:
            raise ValueError(f"{model.__name__} is not a searchable model")

        fts_query = _fts_query(query)
        if not fts_query:
            return ordered_by_ids(model, [])

        ids = self._ranked_ids(fts, fts_query)
        if model is Topic:
            seen = set(ids)
            ids += [pk for pk in self._topic_body_ids(fts_query) if pk not in seen]
        return ordered_by_ids(model, ids)

@override
def index(self, instance: Model) -> None:
    pass

@override
def update(self, instance: Model) -> None:
    pass

@override
def remove(self, instance: Model) -> None:
    pass

@override
def reindex(self, models: Sequence[ModelT] | None = None) -> None:
    tables = (
        _FTS_TABLES.values()
        if models is None
        else [_FTS_TABLES[m] for m in models if m in _FTS_TABLES]
    )
    for fts in tables:
        db.session.execute(text(f"INSERT INTO {fts}({fts}) VALUES ('rebuild')"))
    db.session.commit()

def _ranked_ids(self, fts: str, fts_query: str) -> list[int]:
    # `fts` is an internal constant, never user input. bm25() returns
    # a lower score for better matches, so ascending order is best-first.
    stmt = text(f"SELECT rowid FROM {fts} WHERE {fts} MATCH :q ORDER BY bm25({fts}) LIMIT :lim")
    rows = db.session.execute(stmt, {"q": fts_query, "lim": _SEARCH_LIMIT})
    return list(rows.scalars())

def _topic_body_ids(self, fts_query: str) -> list[int]:
    # A topic also matches on its opening post's body (parity with the
    # `sql` backend), indexed in posts_fts.
    stmt = text(
        "SELECT t.id FROM topics t "
        "JOIN posts_fts ON posts_fts.rowid = t.first_post_id "
        "WHERE posts_fts MATCH :q ORDER BY bm25(posts_fts) LIMIT :lim"
    )
    rows = db.session.execute(stmt, {"q": fts_query, "lim": _SEARCH_LIMIT})
    return list(rows.scalars())

@override
def search(self, model: ModelT, query: str) -> Select[Any]:
    fts = _FTS_TABLES.get(model)
    if fts is None:
        raise ValueError(f"{model.__name__} is not a searchable model")

    fts_query = _fts_query(query)
    if not fts_query:
        return ordered_by_ids(model, [])

    ids = self._ranked_ids(fts, fts_query)
    if model is Topic:
        seen = set(ids)
        ids += [pk for pk in self._topic_body_ids(fts_query) if pk not in seen]
    return ordered_by_ids(model, ids)

def ordered_by_ids(model: ModelT, ids: Sequence[int]) -> Select[Any]:
    """Build a `select(model)` restricted to `ids` and ordered to match
    their sequence - the shared shape every index-backed backend returns
    from `search()` once it has resolved a ranked list of primary keys.
    An empty `ids` yields a statement that matches nothing.
    """
    pk_col = inspect(model).primary_key[0]
    if not ids:
        return select(model).where(sql_false())
    ordering = case({pk: rank for rank, pk in enumerate(ids)}, value=pk_col)
    return select(model).where(pk_col.in_(ids)).order_by(ordering)

@abstractmethod
def index(self, instance: Model) -> None:
    """Add a newly created `instance` to the index. No-op for
    backends where the row itself is the index.
    """

@abstractmethod
def update(self, instance: Model) -> None:
    """Refresh the index entry for an already-indexed `instance`."""

@abstractmethod
def remove(self, instance: Model) -> None:
    """Remove `instance` from the index (e.g. on delete)."""

@abstractmethod
def reindex(self, models: Sequence[ModelT] | None = None) -> None:
    """Rebuild the index for `models` (default: all models this
    backend knows about).
    """

def __init__(self, *args: Any, user: User | None = None, **kwargs: Any):
    self.user = real(user) if user is not None else real(current_user)
    super().__init__(*args, **kwargs)

    self.forum_id.query_factory = lambda: Forum.get_accessible(self.user)

    has_viewhidden = bool(
        self.user.is_authenticated and self.user.permissions.get("viewhidden")
    )
    if not has_viewhidden:
        choices = cast("list[tuple[Any, str]]", self.state.choices or [])
        self.state.choices = [choice for choice in choices if choice[0] != "hidden"]

def get_results(self):
    query = self.search_query.data or ""
    if self.search_type.data == "user":
        return search_users(query)

    return search_forums(
        query,
        self.user,
        content_type=self.content_type.data or "topic",
        forum=self.forum_id.data,
        author=self.author.data,
        date_from=self.date_from.data,
        date_to=self.date_to.data,
        state=self.state.data or "",
    )

def search_snippet(instance: Topic | Post, query: str) -> Markup:
    """Returns a highlighted content preview of `instance` (a `Topic` or
    `Post` search result) for `query`, via the active search backend.
    """
    if isinstance(instance, Topic):
        content = instance.first_post.content if instance.first_post else ""
    else:
        content = instance.content
    return flaskbb_search.snippet(type(instance), instance.id, content, query)

class Search(MethodView):
    form = SearchForm

    def get(self):
        return render_template("search/search_form.html", form=self.form(), result=None)

    def post(self):
        form = self.form()
        result = None
        if form.validate_on_submit():
            result = {
                key: db.session.execute(stmt).unique().scalars().all()
                for key, stmt in form.get_results().items()
            }

        return render_template("search/search_form.html", form=form, result=result)

def post(self):
    form = self.form()
    result = None
    if form.validate_on_submit():
        result = {
            key: db.session.execute(stmt).unique().scalars().all()
            for key, stmt in form.get_results().items()
        }

    return render_template("search/search_form.html", form=form, result=result)

@impl(tryfirst=True)
def flaskbb_load_blueprints(app: FlaskBB):
    search = Blueprint("search", __name__)
    register_view(search, routes=["/search"], view_func=Search.as_view("search"))

    app.register_blueprint(search, url_prefix=app.config["FORUM_URL_PREFIX"])

