def flaskbb_load_internal_setting_groups():
    return [
        general_group,
        auth_group,
        misc_group,
        attachments_group,
        appearance_group,
    ]

def build_form(group: SettingGroup) -> type[FlaskBBForm]:
    """Dynamically create a FlaskForm subclass with one field per setting
    in the group. Field keys stay UPPER_CASE to match the setting keys.
    """
    attrs = {setting.key: setting.wtf_field() for setting in group.settings}
    class_name = f"{group.key.title().replace('_', '')}SettingsForm"
    return type(class_name, (FlaskBBForm,), attrs)

@dataclass(frozen=True)
class SettingsDiff:
    """A settings diff of a group's registered SettingDefinitions
    against what actually has rows in the DB. Used to check whether a
    plugin needs a settings upgrade before actually performing one."""

    missing: tuple[str, ...]  # definition keys with no DB row yet
    obsolete: tuple[str, ...]  # DB rows with no matching definition anymore

    @property
    def has_changes(self) -> bool:
        return bool(self.missing or self.obsolete)

    @property
    def log_output(self) -> str:
        return f"new: {', '.join(self.missing)}, obsolete: {', '.join(self.obsolete)}"

