@override
def apply_changeset(self, model: User, changeset: UserDetailsChange):
    accumulate_errors(lambda v: v.validate(model, changeset), self.validators)
    changeset.assign_to_user(model)
    try_commit(self.db.session, "Could not update details")
    self.plugin_manager.hook.flaskbb_details_updated(user=model, details_update=changeset)

@override
def apply_changeset(self, model: User, changeset: PasswordUpdate):
    accumulate_errors(lambda v: v.validate(model, changeset), self.validators)
    model.password = changeset.new_password
    try_commit(self.db.session, "Could not update password")
    self.plugin_manager.hook.flaskbb_password_updated(user=model)

@override
def apply_changeset(self, model: User, changeset: EmailUpdate):
    accumulate_errors(lambda v: v.validate(model, changeset), self.validators)
    model.email = changeset.new_email
    try_commit(self.db.session, "Could not update email")
    self.plugin_manager.hook.flaskbb_email_updated(user=model, email_update=changeset)

@define(eq=False, order=False, frozen=True, repr=True, hash=False)
class DefaultSettingsUpdateHandler(ChangeSetHandler[User, SettingsUpdate]):
    """
    Updates a user's settings and persists the changes to the database.
    """

    db: SQLAlchemy = field()
    plugin_manager: FlaskBBPluginManager = field()

    @override
    def apply_changeset(self, model: User, changeset: SettingsUpdate):
        changeset.assign_to_user(model)
        try_commit(self.db.session, "Could not update settings")
        self.plugin_manager.hook.flaskbb_settings_updated(user=model, settings_update=changeset)

@override
def apply_changeset(self, model: User, changeset: SettingsUpdate):
    changeset.assign_to_user(model)
    try_commit(self.db.session, "Could not update settings")
    self.plugin_manager.hook.flaskbb_settings_updated(user=model, settings_update=changeset)

@define(eq=False, order=False, hash=False, frozen=True, repr=True)
class CantShareEmailValidator(ChangeSetValidator[User, EmailUpdate]):
    """
    Validates that the new email for the user isn't currently registered by
    another user.
    """

    users: type[User] = field()

    @override
    def validate(self, model: User, changeset: EmailUpdate):
        others = self.users.query.filter(
            self.users.id != model.id,
            func.lower(self.users.email) == changeset.new_email,
        ).count()

        if others != 0:
            raise ValidationError(
                "new_email",
                _("%(email)s is already registered", email=changeset.new_email),
            )

@override
def validate(self, model: User, changeset: EmailUpdate):
    others = self.users.query.filter(
        self.users.id != model.id,
        func.lower(self.users.email) == changeset.new_email,
    ).count()

    if others != 0:
        raise ValidationError(
            "new_email",
            _("%(email)s is already registered", email=changeset.new_email),
        )

class OldEmailMustMatch(ChangeSetValidator[User, EmailUpdate]):
    """
    Validates that the email entered by the user is the current email of the user.
    """

    @override
    def validate(self, model: User, changeset: EmailUpdate):
        if model.email != changeset.old_email:
            raise StopValidation([("old_email", _("Old email does not match"))])

@override
def validate(self, model: User, changeset: EmailUpdate):
    if model.email != changeset.old_email:
        raise StopValidation([("old_email", _("Old email does not match"))])

class EmailsMustBeDifferent(ChangeSetValidator[User, EmailUpdate]):
    """
    Validates that the new email entered by the user isn't the same as the
    current email for the user.
    """

    @override
    def validate(self, model: User, changeset: EmailUpdate):
        if model.email == changeset.new_email:
            raise ValidationError("new_email", _("New email address must be different"))

@override
def validate(self, model: User, changeset: EmailUpdate):
    if model.email == changeset.new_email:
        raise ValidationError("new_email", _("New email address must be different"))

class PasswordsMustBeDifferent(ChangeSetValidator[User, PasswordUpdate]):
    """
    Validates that the new password entered by the user isn't the same as the
    current email for the user.
    """

    @override
    def validate(self, model: User, changeset: PasswordUpdate):
        if model.check_password(changeset.new_password):
