def escape_like(term: str) -> str:
    """Escape LIKE metacharacters in a user-supplied search term so
    literal `%`/`_` in the input aren't interpreted as SQL wildcards.
    """
    return term.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")

def slugify(text: str, delim: str = "-"):
    """Generates an slightly worse ASCII-only slug.
     Taken from the Flask Snippets page.

    :param text: The text which should be slugified
    :param delim: Default "-". The delimeter for whitespace
    """
    text = unidecode.unidecode(text)
    result: list[str] = []
    for word in _punct_re.split(text.lower()):
        if word:
            result.append(word)
    return str(delim.join(result))

def render_template(template: str, **context: Any):  # pragma: no cover
    """A helper function that uses the `render_theme_template` function
    without needing to edit all the views
    """
    if current_user.is_authenticated and current_user.theme:
        theme = current_user.theme
    else:
        theme = session.get("theme", flaskbb_config["DEFAULT_THEME"])
    return render_theme_template(theme, template, **context)

def is_htmx_request() -> bool:
    """Whether the current request came from htmx."""
    return request.headers.get("HX-Request") == "true"

def _htmx_current_page() -> str | None:
    """The page an htmx request was sent from, relative so that it is safe to
    redirect to without ALLOWED_HOSTS, unlike the absolute referrer.
    """
    if not is_htmx_request():
        return None

    current = urlsplit(request.headers.get("HX-Current-URL", ""))
    if current.query:
        return f"{current.path}?{current.query}"
    return current.path

@dataclass(frozen=True)
class ForumRow:
    forum: "Forum"
    forumsread: "ForumsRead | None"

    def __iter__(self):
        return iter((self.forum, self.forumsread))

@dataclass(frozen=True)
class CategoryForums:
    category: "Category | None"
    forums: list[ForumRow]

    def __iter__(self):
        return iter((self.category, self.forums))

def _group_forums_by_category(
    query_result: Iterable[Row[*tuple[Any, ...]]],
    user: "User",
) -> Iterable[CategoryForums]:
    it = itertools.groupby(query_result, operator.itemgetter(0))

    if user.is_authenticated:
        for category, rows in it:
            forum_rows: list[ForumRow] = []
            for row in rows:
                forum_rows.append(ForumRow(row[1], row[2]))
            yield CategoryForums(category, forum_rows)
    else:
        for category, rows in it:
            forum_rows = []
            for row in rows:
                forum_rows.append(ForumRow(row[1], None))
            yield CategoryForums(category, forum_rows)

def get_online_users() -> Sequence["User"]:
    """Returns the users that were online within ONLINE_LAST_MINUTES."""
    from flaskbb.user.models import User

    stmt = select(User).order_by(User.username)
    if current_app.config["REDIS_ENABLED"]:
        redis_client: Redis = current_app.extensions["redis"]
        try:
            user_ids = cast(
                list[bytes],
                redis_client.zrangebyscore(  # pyright: ignore[reportUnknownMemberType]
                    ONLINE_USERS_KEY, time.time() - _online_window(), "+inf"
                ),
            )
            return db.session.scalars(
                stmt.where(User.id.in_([int(user_id) for user_id in user_ids]))
            ).all()
        except RedisError:
            logger.warning("Could not get the online users", exc_info=True)
    return db.session.scalars(stmt.where(User.lastseen >= time_diff())).all()

def is_online(user: "User"):
    """A simple check to see if the user was online within a specified
    time range

    :param user: The user who needs to be checked
    """
    if not user.lastseen:
        return False
    return user.lastseen >= time_diff()

def time_utcnow():
    """Returns a timezone aware utc timestamp."""
    return datetime.now(UTC)

def _get_user_locale():
    locale = flaskbb_config.get("DEFAULT_LANGUAGE", "en")
    if current_user.is_authenticated and current_user.language is not None:
        locale = current_user.language
    return locale

def _format_html_time_tag(
    datetime: datetime,
    what_to_display: Literal["date-only", "time-only", "date-and-time"],
):
    if what_to_display == "date-only":
        content = babel_format_date(datetime, locale=_get_user_locale())
    elif what_to_display == "time-only":
        content = babel_format_time(datetime, format="short", locale=_get_user_locale())
    elif what_to_display == "date-and-time":
        content = babel_format_datetime(datetime, tzinfo=UTC, locale=_get_user_locale())
        # While this could be done with a format string, that would
        # hinder internationalization and honestly why bother.
        content += " UTC"
    else:
        raise ValueError("what_to_display argument invalid")  # pyright: ignore[reportUnreachable]

    isoformat = datetime.isoformat()

    return Markup(
        f"""<time datetime="{isoformat}" data-what_to_display="{what_to_display}">
            {content}
        </time>"""
    )

def format_datetime(datetime: datetime):
    """Format the datetime for usage in templates.

    :param value: The datetime object that should be formatted
    :rtype: Markup
    """
    return _format_html_time_tag(datetime, "date-and-time")

def format_date(datetime: datetime):
    """Format the datetime for usage in templates, keeping only the date.

    :param value: The datetime object that should be formatted
    :rtype: Markup
    """
    return _format_html_time_tag(datetime, "date-only")

def format_time(datetime: datetime):
    """Format the datetime for usage in templates, keeping only the time.

    :param value: The datetime object that should be formatted
    :rtype: Markup
    """
    return _format_html_time_tag(datetime, "time-only")

def format_timedelta(delta: timedelta, **kwargs: Any):
    """Wrapper around babel's format_timedelta to make it user language
    aware.
    """
    return babel_format_timedelta(delta, locale=_get_user_locale(), **kwargs)

def get_flaskbb_config(app: Flask, config_file: str | object):
    """Returns ``None`` or the config which is either the path to a config file
    or an object. They can be used by ``app.config.from_pyfile`` or
    by ``app.config.from_object``.

    :param app: The app instance.
    :param config_file: A string which is either a module that can be
                        imported, a path to a config file or an object.
                        If it is ``None``, the ``FLASKBB_SETTINGS`` environment
                        variable is used instead. If that isn't set either, it
                        will search for a 'flaskbb.cfg' file in the instance
                        directory and in the project's root directory and
                        return ``None`` if there is none.
    :raises ConfigNotFoundError: If the given config or ``FLASKBB_SETTINGS``
                                 is neither an existing file nor an
                                 importable object.
    """
    if config_file is not None:
        # config is an object
        if not isinstance(config_file, str):
            return config_file

        # config is a file
        # -> check if it exists in the instance folder
        if os.path.exists(os.path.join(app.instance_path, config_file)):
            return os.path.join(app.instance_path, config_file)

        # -> check if its an absolute path
        if os.path.exists(os.path.abspath(config_file)):
            return os.path.join(os.path.abspath(config_file))

        # config is an importable string
        # import_string raises ValueError for relative paths like '../x.cfg'
        try:
            return import_string(config_file)
        except (ImportStringError, ValueError) as e:
            raise ConfigNotFoundError(
                f"Config {config_file!r} is neither an existing file nor an importable object."
            ) from e
    elif os.environ.get("FLASKBB_SETTINGS", None):
        config_file = os.environ.get("FLASKBB_SETTINGS", "")

        if os.path.exists(os.path.abspath(config_file)):
            return os.path.join(os.path.abspath(config_file))

        # config is an importable string
        try:
            return import_string(config_file)
        except (ImportStringError, ValueError) as e:
            raise ConfigNotFoundError(
                f"Config {config_file!r} from FLASKBB_SETTINGS is neither an "
                "existing file nor an importable object."
            ) from e
    else:
        # this would be so much nicer and cleaner if we wouldn't
        # support the root/project dir.
        # this walks back to flaskbb/ from flaskbb/flaskbb/cli/main.py
        project_dir = os.path.dirname(os.path.dirname(os.path.dirname(__file__)))
        project_config = os.path.join(project_dir, "flaskbb.cfg")

        # instance config doesn't exist
        instance_config = os.path.join(app.instance_path, "flaskbb.cfg")
        if os.path.exists(instance_config):
            return instance_config

        # config in root directory doesn't exist
        if os.path.exists(project_config):
            return project_config

