def get_safe_redirect_url(
    url: str | None,
    allowed_hosts: set[str] | list[str] | str | None,
    fallback: str | None = None,
    require_https: bool = False,
) -> str | None:
    """
    Validate ``url`` and return the URL that should actually be redirected
    to.

    Returns ``fallback`` if ``url`` is missing or fails validation. ``fallback``
    is trusted and is NOT re-validated. Callers must pass something known
    to be safe (e.g. ``url_for("some.view")``), never user input.
    """
    if url is not None:
        url = url.strip()
    if not url:
        return fallback

    normalized = _normalize_url(url)
    normalized_backslashes = _normalize_url(url.replace("\\", "/"))

    if allowed_hosts is None:
        allowed_hosts = set()
    elif isinstance(allowed_hosts, str):
        allowed_hosts = {allowed_hosts}
    elif isinstance(allowed_hosts, list):
        allowed_hosts = set(allowed_hosts)

    if _url_has_allowed_host_and_scheme(
        normalized, allowed_hosts, require_https=require_https
    ) and _url_has_allowed_host_and_scheme(
        normalized_backslashes, allowed_hosts, require_https=require_https
    ):
        return normalized

    return fallback

def delete_settings_from_fixture(group_key: str | None = None) -> None:
    """Deletes settings rows whose definitions no longer exist in the
    registry.

    :param group_key: limit to a single group (e.g. "general"); None
        checks every registered group.
    """
    groups = [setting_registry.group(group_key)] if group_key else setting_registry.all_groups()
    for group in groups:
        valid_keys_lower = {s.key.lower() for s in group.settings}
        existing_rows = db.session.execute(
            sa.select(Setting).where(Setting.group_key == group.key)
        ).scalars()
        for row in existing_rows:
            if row.key.lower() not in valid_keys_lower:
                db.session.delete(row)

    db.session.commit()
    Setting.invalidate_cache()

def create_latest_db(target: str = "default@head"):
    """Creates the database including the schema using SQLAlchemy's
    db.create_all method instead of going through all the database revisions.
    The revision will be set to 'head' which indicates the latest alembic
    revision.

    The loaded plugins, e.g. the ones enabled in a replaced database, have
    their tables created as well, so their branches are stamped too. Not
    ``heads``, it includes the branches of the disabled plugins.

    :param target: The target branch. Defaults to 'default@head'.
    """
    if not database_exists(db.engine.url):
        create_database(db.engine.url)

    db.create_all()
    plugins = {pluggy.get_name(plugin) for plugin in pluggy.get_external_plugins()}
    plugin_heads = [
        script.revision
        for script in alembic.script_directory.get_revisions("heads")
        if not plugins.isdisjoint(script.branch_labels)
    ]
    alembic.stamp(target=[target, *plugin_heads])

def has_migrations(plugin: Any):
    migrations_path = os.path.join(plugin.__path__[0], "migrations")
    if os.path.exists(migrations_path) and len(os.listdir(migrations_path)) != 0:
        return True
    return False

def run_plugin_migrations(plugins: list[str] | None = None):
    """Runs the migrations for a list of plugins.

    :param plugins: A iterable of plugin names to run the migrations for. If set
                    to ``None``, all external plugin migrations will be run.
    """
    all_plugins: list[str | None] | list[str] = []
    if plugins is None:
        all_plugins = [pluggy.get_name(p) for p in pluggy.get_external_plugins()]
    else:
        all_plugins = plugins

    for plugin_name in all_plugins:
        if plugin_name is None:
            continue

        plugin = pluggy.get_plugin(plugin_name)

        if not has_migrations(plugin):
            logger.debug(f"No migrations found for plugin {plugin_name}")
            continue

        try:
            alembic.upgrade(target=f"{plugin_name}@head")
        except CommandError as exc:
            logger.debug(
                f"Couldn't run migrations for plugin {plugin_name} because of "
                "following exception: ",
                exc_info=exc,
            )

class SelectAllPagination(Pagination):
    """Returned by :meth:`.SQLAlchemy.paginate`. Takes ``select`` and ``session``
    arguments in addition to the :class:`Pagination` arguments.

    .. versionadded:: 3.0
    """

    @t.override
    def _query_items(self) -> list[t.Any]:
        select = self._query_args["select"]
        select = select.limit(self.per_page).offset(self._query_offset)
        session = self._query_args["session"]
        return session.execute(select).all()

    @t.override
    def _query_count(self) -> int:
        select = self._query_args["select"]
        sub = select.options(sa_orm.lazyload("*")).order_by(None).subquery()
        session = self._query_args["session"]
        out = session.execute(sa.select(sa.func.count()).select_from(sub)).scalar()
        return out

