class FlaskBBDomain(Domain):
    def __init__(self, app: Flask):
        self.app = app
        super().__init__()

        # Plugin translations
        with self.app.app_context():
            self.plugin_translations = pluggy.hook.flaskbb_load_translations()

    @override
    def get_translations(self):
        """Returns the correct gettext translations that should be used for
        this request.  This will never fail and return a dummy translation
        object if used outside of the request or if a translation cannot be
        found.
        """
        state = get_state(silent=True)

        if state is None:
            return babel.support.NullTranslations()

        locale = get_locale()
        cache = self.get_translations_cache()
        translations = cache.get(str(locale))

        # load them into the cache
        if translations is None:
            dirname = self.get_translations_path(state.app)
            translations = babel.support.Translations.load(dirname, locale, domain=self.domain)
            # now load and add the plugin translations - only a real
            # Translations catalog can merge others into itself
            if isinstance(translations, babel.support.Translations):
                for plugin in self.plugin_translations:
                    logger.debug(f"Loading plugin translation from: {plugin}")
                    plugin_translation = babel.support.Translations.load(
                        dirname=plugin, locales=locale, domain="messages"
                    )

                    if isinstance(plugin_translation, babel.support.Translations):
                        translations.add(plugin_translation)

            self.cache[str(locale)] = translations

        return translations

@override
def get_translations(self):
    """Returns the correct gettext translations that should be used for
    this request.  This will never fail and return a dummy translation
    object if used outside of the request or if a translation cannot be
    found.
    """
    state = get_state(silent=True)

    if state is None:
        return babel.support.NullTranslations()

    locale = get_locale()
    cache = self.get_translations_cache()
    translations = cache.get(str(locale))

    # load them into the cache
    if translations is None:
        dirname = self.get_translations_path(state.app)
        translations = babel.support.Translations.load(dirname, locale, domain=self.domain)
        # now load and add the plugin translations - only a real
        # Translations catalog can merge others into itself
        if isinstance(translations, babel.support.Translations):
            for plugin in self.plugin_translations:
                logger.debug(f"Loading plugin translation from: {plugin}")
                plugin_translation = babel.support.Translations.load(
                    dirname=plugin, locales=locale, domain="messages"
                )

                if isinstance(plugin_translation, babel.support.Translations):
                    translations.add(plugin_translation)

        self.cache[str(locale)] = translations

    return translations

def translations_are_compiled() -> bool:
    translations_folder = os.path.join(current_app.root_path, "translations")
    return all(
        os.path.exists(os.path.splitext(po_file)[0] + ".mo")
        for po_file in glob.glob(os.path.join(translations_folder, "*/LC_MESSAGES/messages.po"))
    )

def compile_translations(include_plugins: bool = False):
    """Compiles all translations.

    :param include_plugins: If set to `True` it will also compile the
                            translations for all plugins.
    """
    translations_folder = os.path.join(current_app.root_path, "translations")
    subprocess.call(["pybabel", "compile", "-d", translations_folder])

    if include_plugins:
        for plugin in pluggy.list_name():
            compile_plugin_translations(plugin)

def get_avatar_upload_path() -> str:
    upload_path = current_app.config["AVATAR_UPLOAD_PATH"]
    if upload_path is None:
        return os.path.join(current_app.static_folder or "static", "uploads", "avatar")
    return upload_path

def get_avatar_url(avatar: str | None) -> str:
    # FlaskBB 2.x stored a link to an external image instead of an uploaded file
    if avatar and avatar.startswith(("http://", "https://")):
        return avatar
    return url_for("uploads.avatar", avatar=avatar)

def get_avatar_filename(username: str, filename: str | None) -> str:
    if filename:
        file_ext = os.path.splitext(filename)[1]
        return secure_filename("avatar_" + username + file_ext)
    return secure_filename("avatar_" + username)

def delete_avatar_file(filename: str | None):
    if not filename:
        logger.warning("avatar filename not provided - nothing to delete.")
        return

    file_path = Path(get_avatar_upload_path(), filename)
    try:
        file_path.unlink(missing_ok=True)
    except PermissionError:
        logger.error(f"You do not have permission to delete this file: {filename}")
    except IsADirectoryError:
        logger.error(f"The specified path is a directory, not a file: {filename}")
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")

def get_attachment_upload_path() -> str:
    upload_path = current_app.config["ATTACHMENT_UPLOAD_PATH"]
    if upload_path is None:
        return os.path.join(current_app.static_folder or "static", "uploads", "attachments")
    return upload_path

def delete_attachment_file(post_id: int, stored_filename: str):
    file_path = Path(get_attachment_upload_path(), str(post_id), stored_filename)
    try:
        file_path.unlink(missing_ok=True)
        try:
            file_path.parent.rmdir()
        except OSError:
            pass
    except PermissionError:
        logger.error(f"You do not have permission to delete this file: {stored_filename}")
    except IsADirectoryError:
        logger.error(f"The specified path is a directory, not a file: {stored_filename}")
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")

def scan_attachment_storage() -> dict[str, dict[str, float]]:
    """Maps every directory below the attachment upload path to the files it
    holds and their modification times.
    """
    root = get_attachment_upload_path()
    storage: dict[str, dict[str, float]] = {}
    if not os.path.isdir(root):
        return storage

    with os.scandir(root) as entries:
        for entry in entries:
            # only the <post_id> directories flaskbb creates itself are
            # scanned - symlinks are never followed
            if not entry.is_dir(follow_symlinks=False):
                continue

            with os.scandir(entry.path) as files:
                storage[entry.name] = {
                    file.name: file.stat().st_mtime
                    for file in files
                    if file.is_file(follow_symlinks=False)
                }

    return storage

def create_upload_directory(app: Flask):
    with app.app_context():
        for upload_path in (get_avatar_upload_path(), get_attachment_upload_path()):
            if os.path.exists(upload_path):
                continue

            logger.info(f"Creating upload path: {upload_path}")
            os.makedirs(upload_path, exist_ok=True)

