        key="dummy_plugin",
        name="Dummy",
        description="Dummy settings",
        settings=(
            IntSetting(key="OLD", value=1, name="Old", description="Installed setting"),
            IntSetting(key="NEW", value=2, name="New", description="Added by an update"),
        ),
